      var topPosition = fixedTopTS.css('position');
      if (topPosition === 'fixed') {
        if (topAttachTS) {
          scrollAdjustmentTS();
        } else {
          var anchorHeight = anchor.outerHeight() - 1;
          fixedTopTS.css('top', anchorHeight + initialTopTS);
        }
      } else {
        fixedTopTS.css('top', initialTopTS);
